// Match a URL against App Router style folders; most specific pattern wins.
const routes = ["/blog", "/blog/[slug]", "/shop/[...parts]", "/docs/[[...parts]]", "/docs/intro"];

function score(seg) { // lower = more specific
  if (seg.startsWith("[[...")) return 3;
  if (seg.startsWith("[...")) return 2;
  if (seg.startsWith("[")) return 1;
  return 0;
}

function tryMatch(route, urlParts) {
  const segs = route.split("/").filter(Boolean);
  const params = {};
  for (let i = 0; i < segs.length; i++) {
    const s = segs[i];
    if (s.startsWith("[[...")) { params[s.slice(5, -2)] = urlParts.slice(i); return params; }
    if (s.startsWith("[...")) {
      if (urlParts.length <= i) return null; // needs one or more
      params[s.slice(4, -1)] = urlParts.slice(i); return params;
    }
    if (i >= urlParts.length) return null;
    if (s.startsWith("[")) params[s.slice(1, -1)] = urlParts[i];
    else if (s !== urlParts[i]) return null;
  }
  return segs.length === urlParts.length ? params : null;
}

function resolve(url) {
  const parts = url.split("/").filter(Boolean);
  let best = null;
  for (const r of routes) {
    const p = tryMatch(r, parts);
    if (!p) continue;
    const sc = r.split("/").filter(Boolean).map(score);
    const key = Math.max(0, ...sc) * 10 + sc.reduce((a, b) => a + b, 0);
    if (!best || key < best.key) best = { r, p, key };
  }
  return best ? best.r + " " + JSON.stringify(best.p) : "404";
}

for (const u of ["/blog", "/blog/hello", "/shop", "/shop/a/b", "/docs", "/docs/intro", "/docs/x/y"])
  console.log(u + " -> " + resolve(u));

// Which error boundary catches an error? error.js sits INSIDE its own layout,
// so a layout error goes to the PARENT segment's boundary.
const tree = [
  { name: "app (root)", error: false },
  { name: "dashboard", error: true },
  { name: "settings", error: true },
];

function whoCatches(failingSegment, failingPart) {
  // failingPart is "layout" or "page"
  let idx = tree.findIndex(s => s.name === failingSegment);
  // a page error is caught by the boundary of the same segment;
  // a layout error starts looking one level up
  if (failingPart === "layout") idx -= 1;
  for (let i = idx; i >= 0; i--) {
    if (tree[i].error) return tree[i].name + "/error.js";
  }
  return "global-error.js (replaces the root layout)";
}

const cases = [
