}

// Can this value cross the server -> client boundary? (simplified check)
function serializable(v, path) {
  path = path || "props";
  if (v === null || ["string", "number", "boolean", "bigint", "undefined"].includes(typeof v)) return null;
  if (typeof v === "function") return path + " is a function";
  if (typeof v === "symbol") return path + " is a symbol";
  if (v instanceof Date || v instanceof Map || v instanceof Set) return null;
  if (Array.isArray(v)) {
    for (let i = 0; i < v.length; i++) { const e = serializable(v[i], path + "[" + i + "]"); if (e) return e; }
    return null;
  }
  const proto = Object.getPrototypeOf(v);
  if (proto !== Object.prototype && proto !== null) return path + " is a class instance (" + proto.constructor.name + ")";
  for (const k of Object.keys(v)) { const e = serializable(v[k], path + "." + k); if (e) return e; }
  return null;
}

