// Two server caches: request memoization (one render) and a tagged data cache.
let dbValue = "v1", dbReads = 0;
const dataCache = new Map();   // key -> { value, tag }

function fetchData(key, tag) { // like fetch() with next.tags
  if (dataCache.has(key)) return dataCache.get(key).value;
  dbReads++;
  const v = dbValue;
  dataCache.set(key, { value: v, tag });
  return v;
}

function revalidateTag(tag) {
  for (const [k, e] of dataCache) if (e.tag === tag) dataCache.delete(k);
}

function renderRequest() {
  const memo = new Map();      // request memoization lives for one render only
  const get = (k, t) => {
    if (!memo.has(k)) memo.set(k, fetchData(k, t));
    return memo.get(k);
  };
  // layout, page and generateMetadata all ask for the same data
  return [get("post", "posts"), get("post", "posts"), get("post", "posts")].join(",");
}

