console.log("request 3 (after revalidateTag):", renderRequest(), "db reads:", dbReads);

// ISR: serve the cached page, regenerate once in the background when stale.
let clock = 0;            // fake time in seconds
let version = 1;          // pretend CMS content version
let cmsDown = false;
let cache = { html: "page v1", at: 0 };
let regenerating = false;
let regenCount = 0;
const REVALIDATE = 60;

function render() {
  if (cmsDown) throw new Error("CMS failed");
  regenCount++;
  return "page v" + version;
}

function request() {
  const stale = clock - cache.at >= REVALIDATE;
  const served = cache.html;               // always answer from the cache
  if (stale && !regenerating) {
    regenerating = true;                   // dedupe: one regeneration per path
    try { cache = { html: render(), at: clock }; }
    catch (e) { /* keep last good version, retry on a later request */ }
    regenerating = false;
  }
  return served;
}

function at(t, label) {
  clock = t;
  console.log("t=" + t + "s " + label + " -> " + request() + " (renders so far: " + regenCount + ")");
}

at(10, "fresh");
version = 2;
at(70, "stale, triggers regen");
at(71, "new version");
cmsDown = true; version = 3;
at(140, "stale, CMS down");
at(141, "still last good");
cmsDown = false;
at(142, "retry works");
at(143, "now v3");

// A tiny matcher in the style of Next.js middleware / proxy config.
function toRegex(pattern) {
  if (pattern.startsWith("/(") ) return new RegExp("^" + pattern + "$"); // raw regex form
  const src = pattern
    .replace(/\/:path\*/g, "(?:/.*)?")   // zero or more segments
    .replace(/\/:path\+/g, "/.+");        // one or more segments
  return new RegExp("^" + src + "$");
}

const matcher = [
  "/dashboard/:path*",
  "/api/:path+",
  "/((?!api|_next/static|_next/image|favicon.ico).*)",
];

function runs(url) {
  return matcher.filter(m => toRegex(m).test(url));
}

for (const u of ["/dashboard", "/dashboard/a/b", "/api", "/api/users", "/_next/static/x.js", "/about"]) {
  const hit = runs(u);
  console.log(u + " -> " + (hit.length ? "middleware runs via " + hit.length + " pattern(s)" : "skipped"));
}
